#include <stdio.h>

static int cnt[1001];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long total = 0;
    for (int i = 0; i < n; i++) {
        int p;
        if (scanf("%d", &p) != 1) return 0;
        cnt[p]++;
        total += p;
    }

    /*
     * Estrategia otima: ordenar os precos em ordem decrescente e, a cada
     * grupo de tres consecutivos, o terceiro (o mais barato do grupo) e
     * gratis. Ou seja, os produtos gratuitos sao os de indices 2, 5, 8, ...
     * (0-based) na ordenacao decrescente.
     *
     * Prova de otimalidade: se g1 >= g2 >= ... >= gk sao os chocolates
     * gratuitos de qualquer solucao viavel, cada gi precisa de dois pagos
     * com valor >= gi; logo existem pelo menos 3i chocolates com valor >= gi,
     * o que implica gi <= p_{3i}. Portanto a soma economizada e no maximo
     * soma de p_3 + p_6 + ..., atingida pela estrategia gulosa.
     *
     * Implementado com counting sort (P <= 1000): percorre os valores do
     * maior para o menor mantendo a posicao global, standing em indices
     * congruentes a 2 (mod 3).
     */
    long long idx = 0;
    for (int v = 1000; v >= 1; v--) {
        for (int k = 0; k < cnt[v]; k++) {
            if (idx % 3 == 2) total -= v;
            idx++;
        }
    }

    printf("%lld\n", total);
    return 0;
}
